!function(e){"use strict";app.factory("proformaService",(function($injector){let url="Venta/Proforma/",mS=$injector.get("mainService"),fS=$injector.get("formulario"),service={getAll:function(query){return mS.getData("get",url+"Get?json="+JSON.stringify(query),null,!0).then(response=>{if("0"===response.code)throw response;if("1"===response.code){let mainData,proformasRepos=(JSON.parse(response.payload)||[])[0],{totalRecords:totalRecords,totalDocument:totalDocument}=proformasRepos[0],proformas;return{proformas:proformasRepos.map(item=>({comprobante:"Proforma",entidad:item.entidad,codEstab:item.codEstab,idProforma:item.idProforma,idDocumento:item.idDocumento,idTipoDocumento:item.idTipoDocumento,idCliente:item.idCliente,nombreComercial:item.nombreComercial,telefonoEstablecimiento:item.telefonoEstablecimiento,correo:item.correo,fechaEmision:item.fechaEmision,total:item.total,nroDocumento:item.nroDocumento,serieComprobante:item.nroDocumento,nombreFiscal:item.nombreFiscal,nroIdentificacion:item.nroIdentificacion,telefono:item.telefono,usuario:item.usuario,estadoDoc:item.estadoDoc,codDoc:item.codDoc,rowColor:item.rowColor,codEstado:item.codEstado})),dataTotals:{totalRecords:totalRecords,totalDocument:totalDocument}}}}).catch(error=>{throw console.log("obtener datos->proforma service",error),error})},queryMapper:function({data:data,cliente:cliente,detalles:detalles}){let formattedDateForInsert=null;if(formattedDateForInsert=moment(data.fechaEmision).isBefore(new Date,"day")?moment(data.fechaEmision).startOf("day").toDate():data.fechaEmision,0===cliente.idCliente&&!cliente.razonSocialComprador&&!cliente.identificacionComprador)throw new Error("Datos de cliente no proporcionados");let proforma=Object.assign({},data);return proforma.idCliente=cliente.idCliente,proforma.identificacionComprador=cliente.identificacionComprador,proforma.razonSocialComprador=cliente.razonSocialComprador,proforma.direccionComprador=cliente.direccionComprador,proforma.email=cliente.email,proforma.telefono=cliente.telefono,proforma.fechaEmision=fS.formatDateTimeZone(formattedDateForInsert),{proforma:proforma,detalle:service.detalleMapperTo(detalles)}},detalleMapperTo:function(detalles){let tempDetails=[],orderIndex=1;for(let item of detalles)tempDetails.push({orderIndex:orderIndex++,idProformaDetalle:item.idProformaDetalle||0,idArticulo:item.idArticulo,idTarifa:item.idTarifa,idBodega:item.idBodega,idMedida:item.idMedida,idPresentacion:item.idPresentacion||0,idTipoIva:item.idTipoIva,tarifa:item.tarifa,codigoPorcentaje:item.codigoPorcentaje,ice:item.ice,descripcion:item.descripcion,cantidad:item.cantidad,precioCostoNeto:item.precioCostoNeto,precioUnitario:item.precioUnitario,precioConIva:item.precioConIva,valorDescuento:item.valorDescuento,precioTotalSinImpuesto:item.precioTotalSinImpuesto||0,porcentajeDescuento:item.porcentajeDescuento,total:item.total,nota:item.nota});return tempDetails},save:function(data){return mS.getData("post",url+"Insert/",data,!0).then(response=>"0"===response.code?response:"1"===response.code?response:void 0)},update:function(id,data){return mS.getData("put",url+"Update/"+id,data,!0).then(response=>"0"===response.code?response:"1"===response.code?response:void 0)},delete:function(id){return mS.getData("delete",url+"Delete/"+id,null,!0).then(response=>"0"===response.code?response:"1"===response.code?response:void 0)}};return service}))}(window.angular);